import{_ as t,o as a,c as o,a3 as r}from"./chunks/framework.CWpttWmj.js";const m=JSON.parse('{"title":"Quick start","description":"","frontmatter":{},"headers":[],"relativePath":"guide/quick-start.md","filePath":"guide/quick-start.md","lastUpdated":null}'),n={name:"guide/quick-start.md"};function s(i,e,h,d,c,l){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick start&quot;">​</a></h1><p>Five steps, about five minutes, most of which is waiting for a timer between two transactions.</p><div class="tip custom-block"><p class="custom-block-title">Before you start</p><p>You need a wallet that can add a custom network, and some testnet gas. Both are covered in <a href="/docs/guide/connecting-a-wallet.html">Connecting a wallet</a> — do that first if you haven&#39;t.</p></div><h2 id="_1-open-the-app-and-connect" tabindex="-1">1. Open the app and connect <a class="header-anchor" href="#_1-open-the-app-and-connect" aria-label="Permalink to &quot;1. Open the app and connect&quot;">​</a></h2><p>Open the Arc Names app and press <strong>Connect</strong>. Approve the connection in your wallet.</p><p>If your wallet is on the wrong network, a banner appears at the top of the app with a button to switch. Arc Names only works on Arc Testnet — chain ID <code>5042002</code>.</p><h2 id="_2-search-for-a-name" tabindex="-1">2. Search for a name <a class="header-anchor" href="#_2-search-for-a-name" aria-label="Permalink to &quot;2. Search for a name&quot;">​</a></h2><p>Type into the search box. You don&#39;t type the <code>.arc</code> — the app appends it.</p><p>The result tells you one of four things:</p><table tabindex="0"><thead><tr><th>Result</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Available</strong></td><td>Free to register, with the yearly price shown.</td></tr><tr><td><strong>Taken</strong></td><td>Registered to someone else, with the owner and expiry date.</td></tr><tr><td><strong>In grace period</strong></td><td>Expired, but still locked to its previous owner for 90 days. You cannot register it yet — the page shows the date it frees up.</td></tr><tr><td><strong>Not a usable name</strong></td><td>The name breaks a rule. See <a href="/docs/guide/registering.html#what-makes-a-name-valid">what makes a name valid</a>.</td></tr></tbody></table><p>Names are lowercase, and may contain letters, digits and hyphens. Length changes the price — see <a href="/docs/guide/pricing.html">Pricing &amp; rarity</a>.</p><h2 id="_3-commit" tabindex="-1">3. Commit <a class="header-anchor" href="#_3-commit" aria-label="Permalink to &quot;3. Commit&quot;">​</a></h2><p>Press <strong>Register</strong> on an available name and the app sends a <strong>commitment</strong> — a hash of the name, your address, and a random secret. It reveals nothing about which name you want.</p><p>This is the front-running defence. Without it, anyone watching the mempool could see your registration, pay more gas, and take the name out from under you. The commitment goes first, alone, and is meaningless to an observer.</p><div class="danger custom-block"><p class="custom-block-title">Don&#39;t clear browser storage mid-registration</p><p>The secret is stored in your browser. Lose it and the commitment is unusable — you&#39;ll have to start again and pay the commit gas twice. Don&#39;t clear site data, and don&#39;t switch browsers between step 3 and step 5.</p></div><h2 id="_4-wait-out-the-timer" tabindex="-1">4. Wait out the timer <a class="header-anchor" href="#_4-wait-out-the-timer" aria-label="Permalink to &quot;4. Wait out the timer&quot;">​</a></h2><p>A countdown appears. The contract requires a minimum wait between commit and register, so that the commitment is already buried in a past block before the name becomes public.</p><p>There is also a maximum. If you wait too long the commitment expires and you start over — the app shows this as an expired state with a button to restart. Don&#39;t walk away for an hour.</p><h2 id="_5-register" tabindex="-1">5. Register <a class="header-anchor" href="#_5-register" aria-label="Permalink to &quot;5. Register&quot;">​</a></h2><p>When the countdown hits zero, press <strong>Register</strong>. This second transaction reveals the name, pays for the duration you chose, and mints the name to your wallet as an NFT.</p><p>Pick your duration before confirming. You pay per year, and registering for longer costs proportionally more but only ever costs one transaction. Minimum is 28 days, maximum is 100 years.</p><p>Any overpayment is refunded by the contract in the same transaction — the app quotes a small buffer over the exact price so the transaction doesn&#39;t fail if the price moves between the quote and the mint.</p><h2 id="you-have-a-name-now-what" tabindex="-1">You have a name. Now what? <a class="header-anchor" href="#you-have-a-name-now-what" aria-label="Permalink to &quot;You have a name. Now what?&quot;">​</a></h2><p>Registration does more than mint the token. In the same transaction the controller also binds the default resolver to your name and sets its address record to point at you — so <code>alice.arc</code> already resolves to your wallet the moment it&#39;s minted. Nothing further is required to receive payments.</p><p>Two optional steps remain, one transaction each:</p><ol><li><strong><a href="/docs/guide/primary-name.html">Set it as your primary name</a></strong> — so apps show <code>alice.arc</code> instead of your address. This is the <em>reverse</em> direction and is <strong>not</strong> set automatically. Open <strong>My names → Records → Use as primary name</strong>.</li><li><strong><a href="/docs/guide/records.html">Fill in your profile</a></strong> — avatar, website, description, social handles. Same dialog. Each record is its own transaction.</li></ol><h2 id="then-keep-it" tabindex="-1">Then keep it <a class="header-anchor" href="#then-keep-it" aria-label="Permalink to &quot;Then keep it&quot;">​</a></h2><p>Names expire. Put the expiry date in your calendar and read <a href="/docs/guide/renewals.html">Renewals &amp; expiry</a> — particularly the part about the 90-day grace period, which is the thing people misunderstand most often.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>&quot;Can&#39;t reach the Arc network right now.&quot;</strong> The app can&#39;t talk to the RPC endpoint. Check your connection and press <em>Try again</em>. If it persists, the RPC endpoint is down or misconfigured — see <a href="/docs/safety.html#when-the-app-cant-reach-the-network">Safety</a>.</p><p><strong>The search box shows nothing at all.</strong> Same cause as above. A failed lookup shows an error card with a <em>Try again</em> button.</p><p><strong>&quot;This name has no resolver.&quot;</strong> Unusual for a name registered through the app, since the controller binds one during registration. You&#39;ll see this on a name whose resolver was later unset, or one registered by other means. Press <strong>Set a resolver</strong> and you can then write records. See <a href="/docs/guide/records.html#binding-a-resolver">Records &amp; profile</a>.</p><p><strong>My transaction reverted.</strong> Every revert reason is listed with its cause in the <a href="/docs/reference/faq.html#transaction-errors">FAQ</a>.</p>',33)])])}const u=t(n,[["render",s]]);export{m as __pageData,u as default};
